import { DialogHeader } from '@kerfjs/ui/dialog-header';
import '@kerfjs/ui/layout.css';
import './item-dialog.css';

type Item = { id: string; name: string; summary: string; owner: string; updated: string };
type Props = { open: boolean; items: Item[]; selectedId: string; onSelect: (id: string) => void; onCancel: () => void; onConfirm: (id: string) => void };

export function ItemDialog({ open, items, selectedId, onSelect, onCancel, onConfirm }: Props) {
  const selected = items.find(item => item.id === selectedId) ?? items[0];
  if (!selected) return null;

  return (
    <dialog open={open} className="item-dialog kui-layout" aria-labelledby="item-dialog-title" aria-describedby="item-dialog-summary">
      <DialogHeader id="item-dialog-title" title="Choose an item" />
      <div className="dialog-scroll">
        <p id="item-dialog-summary">Review an item and confirm your selection.</p>
        <div className="master-detail">
          <div role="listbox" aria-label="Available items" aria-activedescendant={`item-${selected.id}`}>
            {items.map(item => (
              <button id={`item-${item.id}`} key={item.id} type="button" role="option" aria-selected={item.id === selected.id} onClick={() => onSelect(item.id)}>
                {item.name}
              </button>
            ))}
          </div>
          <section className="detail kui-surface" aria-labelledby="selected-item-title">
            <h2 id="selected-item-title">{selected.name}</h2>
            <p>{selected.summary}</p>
            <dl><dt>Owner</dt><dd>{selected.owner}</dd><dt>Updated</dt><dd>{selected.updated}</dd></dl>
          </section>
        </div>
      </div>
      <footer className="dialog-actions">
        <button type="button" onClick={onCancel}>Cancel</button>
        <button type="button" onClick={() => onConfirm(selected.id)}>Use item</button>
      </footer>
    </dialog>
  );
}

