.item-dialog { inline-size: min(52rem, calc(100vw - 2rem)); max-block-size: calc(100dvh - 2rem); grid-template-rows: auto minmax(0, 1fr) auto; padding: 0; }
.dialog-scroll { overflow: auto; padding: var(--kui-space-dialog); }
.master-detail { display: grid; grid-template-columns: minmax(12rem, .8fr) minmax(0, 1.2fr); gap: var(--kui-space-section); }
[role='listbox'] { display: grid; align-content: start; gap: var(--kui-space-control); }
[role='option'] { min-block-size: 2.75rem; text-align: start; }
.detail { padding: var(--kui-space-surface); }
.detail dl { display: grid; grid-template-columns: max-content 1fr; gap: var(--kui-space-control); }
.dialog-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--kui-space-control); padding: var(--kui-space-dialog); }
@media (max-width: 560px) { .master-detail { grid-template-columns: minmax(0, 1fr); } }
